function sharedOpening(words: string[]): string {
  const sorted = [...words].sort();
  const a = sorted[0], b = sorted[sorted.length - 1];
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return a.slice(0, i);
}

